    /// <summary>
    /// SVG nét 24×24. <paramref name="css"/> thêm lớp (ví dụ "i-fill" để tô đặc ngôi sao, tia chớp);
    /// <paramref name="label"/> có giá trị thì biểu tượng được đọc lên, không thì ẩn với trình đọc màn hình.
    /// </summary>
    public static IHtmlContent Svg(string name, int size = 16, string? css = null, double stroke = 2, string? label = null)
    {
        var a11y = label is null ? "aria-hidden=\"true\"" : $"role=\"img\" aria-label=\"{System.Net.WebUtility.HtmlEncode(label)}\"";
        var cls = css is null ? "ic" : "ic " + css;
        var sw = stroke.ToString(System.Globalization.CultureInfo.InvariantCulture);
        return new HtmlString($"<svg class=\"{cls}\" width=\"{size}\" height=\"{size}\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"{sw}\" stroke-linecap=\"round\" stroke-linejoin=\"round\" {a11y}>{Paths.GetValueOrDefault(name, "")}</svg>");
    }

    public static bool Has(string name) => Paths.ContainsKey(name);
}
